#!/bin/sh
# SPDX-License-Identifier: LGPL-2.1-or-later
# Copyright (c) 2026 the MYIOSDECK author
#
# build-unix.sh <wine-11.4 tree> <wine build dir> <out dir>
#
# Spec 35 Part A: opengl32's unix side for iOS arm64 (minimum iOS 17.0, -O2) as one static
# library, <out dir>/libopengl32_unix.a:
#   unix_thunks.c   generated by this tree's make_opengl (regen.sh), with Wine's table names
#                   __wine_unix_call_funcs / __wine_unix_call_wow64_funcs renamed to
#                   opengl32_upstream_funcs / opengl32_upstream_wow64_funcs
#   unix_wgl.c      Wine's, changed (D7, G1, H2)
#   opengl_ios*.c   the iOS wrappers (B1, E, H): the two tables spec 09's loader binds,
#                   opengl32_unix_call_funcs and opengl32_unix_call_wow64_funcs
# The wrappers' entry list comes from the enum of opengl32's unixlib.h (gen-entries.sh), so every
# entry is wrapped. pgl's header comes from ../pgl (libpgl.a is build-pgl.sh's).
#
# Until regen.sh's output (unix_thunks.c) is committed here, the library is built without it: the
# upstream tables are empty and every program gets B1's "off" answers (spec 12 clarification 8's
# behaviour), so opengl32.dll still loads. The build says so in its output.
#
# Environment: CC, AR (default: xcrun -sdk iphoneos clang / ar), EXTRA_CFLAGS.

set -eu

[ $# -eq 3 ] || { echo "usage: $0 <wine-11.4 tree> <wine build dir> <out dir>" >&2; exit 2; }

HERE=$(cd "$(dirname "$0")" && pwd)
PART=$(cd "$HERE/.." && pwd)
REPO=$(cd "$PART/../.." && pwd)

# refs/ is read only: refuse an out dir inside it (nearest existing parent, links resolved)
REFS=$(cd "$REPO/refs" 2>/dev/null && pwd -P) || REFS=""
if [ -n "$REFS" ]; then
  p=$3; rest=""
  while [ ! -d "$p" ]; do rest="/$(basename "$p")$rest"; p=$(dirname "$p"); done
  case "$(cd "$p" && pwd -P)$rest/" in
    "$REFS/"*) echo "$0: refusing an out dir inside refs/: $3" >&2; exit 1 ;;
  esac
fi

WINE=$(cd "$1" && pwd)
BUILD=$(cd "$2" && pwd)
mkdir -p "$3"
OUT=$(cd "$3" && pwd)
WORK="$OUT/work-opengl32"
OBJ="$WORK/obj"
LOG="$WORK/log"
rm -rf "$WORK"
mkdir -p "$OBJ" "$LOG"

CC=${CC:-"xcrun -sdk iphoneos clang"}
AR=${AR:-"xcrun -sdk iphoneos ar"}

# the generated files: this folder's (regen.sh) when present, else the Wine tree's (identical for
# unixlib.h and unix_thunks.h, regen.sh checks that)
UNIXLIB_H="$WINE/dlls/opengl32/unixlib.h"
[ -f "$HERE/unixlib.h" ] && UNIXLIB_H="$HERE/unixlib.h"
cp "$UNIXLIB_H" "$WORK/unixlib.h"
if [ -f "$HERE/unix_thunks.h" ]; then cp "$HERE/unix_thunks.h" "$WORK/"; else cp "$WINE/dlls/opengl32/unix_thunks.h" "$WORK/"; fi
sh "$HERE/gen-entries.sh" "$WORK/unixlib.h" "$WORK/opengl_ios_entries.h"

COMMON="-arch arm64 -miphoneos-version-min=17.0 -O2 -std=gnu11 -fPIC -fno-strict-aliasing \
 -fasynchronous-unwind-tables -fno-omit-frame-pointer -ffixed-x18 ${EXTRA_CFLAGS:-}"
DEFS="-DWINE_IOS=1 -DWINE_UNIX_LIB -D__WINESRC__ -D_OPENGL32_ -D_REENTRANT"
WARN="-Wall -Wno-unused-function -Wno-unused-variable -Wno-unused-but-set-variable \
 -Wno-pragma-pack -Wno-deprecated-declarations -Wno-unknown-pragmas"
# $WORK first (the entry list, the generated headers), then this folder (unix_private.h and the
# iOS headers replace Wine's), then the shared header overrides of spec 17, then Wine's
INCS="-I$WORK -I$HERE -I$PART/pgl -I$WINE/dlls/opengl32 -I$REPO/out/09-ntdll-processes/include \
 -I$BUILD/include -I$WINE/include"

failed=""
compile() {   # compile <source> <object name> [extra flags...]
  c=$1; n=$2; shift 2
  # shellcheck disable=SC2086
  if $CC $COMMON $DEFS $WARN $INCS "$@" -c "$c" -o "$OBJ/$n.o" > "$LOG/$n.log" 2>&1; then
    echo "$n OK"
  else
    echo "$n FAILED"
    failed="$failed $n"
  fi
}

if [ -f "$HERE/unix_thunks.c" ]; then
  echo "opengl32: generated unix_thunks.c present"
  compile "$HERE/unix_thunks.c" unix_thunks \
    -D__wine_unix_call_funcs=opengl32_upstream_funcs -D__wine_unix_call_wow64_funcs=opengl32_upstream_wow64_funcs
  printf '%s\n' '/* build-unix.sh */' 'const int opengl32_upstream_present = 1;' > "$WORK/upstream_present.c"
else
  echo "opengl32: WARNING: no generated unix_thunks.c in $HERE (run regen.sh): every program gets"
  echo "opengl32: OpenGL off (spec 12 clarification 8's answers); PG_OPENGL=1 is logged and ignored"
  cat > "$WORK/upstream_present.c" <<'EOF'
/* build-unix.sh: a build without the generated unix_thunks.c (spec 35, see regen.sh). The
 * wrappers never call these tables while opengl32_upstream_present is 0. */
#include <stdarg.h>
#include "ntstatus.h"
#include "windef.h"
#include "winbase.h"
#include "unixlib.h"
#include "unix_private.h"
const int opengl32_upstream_present = 0;
const unixlib_entry_t opengl32_upstream_funcs[funcs_count];
const unixlib_entry_t opengl32_upstream_wow64_funcs[funcs_count];
struct opengl_funcs null_opengl_funcs;
const struct registry_entry extension_registry[1];
const int extension_registry_size = 0;
EOF
fi
compile "$WORK/upstream_present.c" upstream_present
compile "$HERE/unix_wgl.c" unix_wgl
for n in opengl_ios opengl_ios_call opengl_ios_tables opengl_ios_pure; do
  compile "$HERE/$n.c" "$n"
done

if [ -n "$failed" ]; then
  echo "FAILED:$failed"
  for f in $failed; do echo "==== $f"; head -60 "$LOG/$f.log"; done
  exit 1
fi

rm -f "$OUT/libopengl32_unix.a"
# shellcheck disable=SC2086
$AR rcs "$OUT/libopengl32_unix.a" "$OBJ"/*.o
echo "built $OUT/libopengl32_unix.a"
